        internal static (Guid, string) GetSimplifiedCredit(AccountCustomerOrSupplierDto supplier)
        {
            var (uuid, xml) = ReplaceValues(Simplified_Credit, supplier);
            return (uuid, xml);
        }

        internal static (Guid, string) GetSimplifiedDebit(AccountCustomerOrSupplierDto supplier)
        {
            var (uuid, xml) = ReplaceValues(Simplified_Debit, supplier);
            return (uuid, xml);
        }

        internal static (Guid, string) GetSimplifiedInvoice(AccountCustomerOrSupplierDto supplier)
        {
            var (uuid, xml) = ReplaceValues(Simplified_Invoice, supplier);
            return (uuid, xml);
        }

        internal static (Guid, string) GetStandardCredit(AccountCustomerOrSupplierDto supplier)
        {
            var (uuid, xml) = ReplaceValues(Standard_Credit, supplier);
            return (uuid, xml);
        }

