        private static (Guid, string) ReplaceValues(string xml, AccountCustomerOrSupplierDto supplier)
        {
            var uuid = Guid.NewGuid();
            string issueDate = DateTime.UtcNow.ToString("yyyy-MM-dd");
            string issueTime = DateTime.UtcNow.ToString("HH:mm:ss");
            string fullXml = xml;
            fullXml = fullXml.Replace("@UUID", uuid.ToString());
            fullXml = fullXml.Replace("@IssueDate", issueDate);
            fullXml = fullXml.Replace("@IssueTime", issueTime);
            fullXml = fullXml.Replace("@PIH", "0".ToSha256HexBase64());
            fullXml = fullXml.Replace("@IdentifierId", supplier.CommercialNumber);
            fullXml = fullXml.Replace("@StreetName", supplier.StreetName);
            fullXml = fullXml.Replace("@BuildNo", supplier.BuildNo);
            fullXml = fullXml.Replace("@CitySubdivisionName", supplier.CitySubdivisionName);
            fullXml = fullXml.Replace("@CityName", supplier.CityName);
            fullXml = fullXml.Replace("@PostalZone", supplier.PostalZone);
            fullXml = fullXml.Replace("@CountryCode", supplier.CountryCode);
            fullXml = fullXml.Replace("@CompanyId", supplier.TaxNumber);
            fullXml = fullXml.Replace("@RegistrationName", supplier.TaxCompanyName);
            fullXml = fullXml.Replace("@ActualDeliveryDate", DateTime.UtcNow.ToDateInvoice());

            if (supplier.CommercialType == CompanyCommercialType.OTH)
            {
                var doc = fullXml.RemovePartyTaxScheme();
                fullXml = doc.ToString(SaveOptions.DisableFormatting);
            }

            return (uuid, fullXml);
        }
    }
